    import { join } from 'node:path';

async function askWorker(file, value) {
      cluster.setupPrimary({ exec: file, args: [], execArgv: [] });
      const worker = cluster.fork();
      const response = once(worker, 'message');
      const exit = once(worker, 'exit');
      worker.send(value);
      const [[answer], [code]] = await Promise.all([response, exit]);
      if (code !== 0) throw new Error('Worker failed');
      return answer;
    }

