function makeRouter() {
      const paths = new Map();
      return {
        add(method, path, handler) {
          if (!paths.has(path)) paths.set(path, new Map());
          paths.get(path).set(method, handler);
        },
        async dispatch(method, request) {
          const url = new URL(request, 'http://localhost');
          const methods = paths.get(url.pathname);
          if (!methods) return 404;
          const handler = methods.get(method);
          return handler ? handler(url) : 405;
        },
      };
    }

