function compose(stack) {
      return async (ctx, endpoint) => {
        let last = -1;
        async function dispatch(index) {
          if (index <= last) throw new Error('next already called');
          last = index;
          const layer = stack[index];
          if (layer) return layer(ctx, () => dispatch(index + 1));
          return endpoint(ctx);
        }
        return dispatch(0);
      };
