function createApp() {
      const stack = [];
      const routes = new Map();
      const key = (method, path) => method + ' ' + path;
      return {
        use(fn) { stack.push(fn); },
        route(method, path, fn) { routes.set(key(method, path), fn); },
        callback() {
          return async (req, res) => {
            try {
              const url = new URL(req.url, 'http://localhost');
              const ctx = { req, res, url };
              const handler = routes.get(key(req.method, url.pathname));
              const result = await compose(stack)(ctx, current => {
                if (handler) return handler(current);
              });
              if (res.writableEnded) return;
              if (!handler) return send(res, 404, { error: 'Not found' });
              send(res, 200, result);
            } catch {
              if (!res.headersSent) send(res, 500, { error: 'Internal error' });
              else res.destroy();
            }
          };
        },
      };
    }

